// A region is either strictly above the diagonal (B), strictly below (A), or on the border (None).
#[derive(PartialEq, Eq)]
enum Region { A, B }

#[spec]
fn region_of(x: i8, y: i8) -> Option<Region> {
    if x > y {
        Some(Region::A)
    } else if y > x {
        Some(Region::B)
    } else {
        None
    }
}

